class Solution:
    def balancedString(self, s: str) -> int:
        from itertools import accumulate
        n = len(s)
        target = n // 4
        idx = {'Q': 0, 'W': 1, 'E': 2, 'R': 3}
        pre = [[0] * (n + 1) for _ in range(4)]
        for i, ch in enumerate(s):
            for k in range(4):
                pre[k][i + 1] = pre[k][i] + (1 if idx[ch] == k else 0)
        best = n
        for i in range(n):
            for j in range(i, n):
                ok = True
                for k in range(4):
                    if pre[k][n] - (pre[k][j + 1] - pre[k][i]) > target:
                        ok = False
                        break
                if ok:
                    best = min(best, j - i + 1)
                    break
        return best

