        int[][] pre = new int[n + 1][4];
        for (int i = 0; i < n; i++) {
            pre[i + 1] = pre[i].clone();
            pre[i + 1][idx(s.charAt(i))]++;
        }
        int best = n;
        for (int i = 0; i < n; i++)
            for (int j = i; j < n; j++) {
                boolean ok = true;
                for (int k = 0; k < 4; k++)
                    if (pre[n][k] - (pre[j + 1][k] - pre[i][k]) > target) { ok = false; break; }
                if (ok) { best = Math.min(best, j - i + 1); break; }
            }
        return best;
    }
    private int idx(char c) { return c == 'Q' ? 0 : c == 'W' ? 1 : c == 'E' ? 2 : 3; }
}

