        int n = s.size(), target = n / 4;
        array<int,4> cnt{0,0,0,0}, win{0,0,0,0};
        auto id = [](char c){ return c=='Q'?0:c=='W'?1:c=='E'?2:3; };
        for (char c : s) cnt[id(c)]++;
        int ans = n, left = 0;
        for (int r = 0; r < n; r++) {
            win[id(s[r])]++;
            bool ok = true;
            for (int k = 0; k < 4; k++) if (cnt[k] - win[k] > target) { ok = false; break; }
